#include <stdio.h>
#include <math.h>
void num_grad(double (*f)(double, double), double x, double y, double h, double *gx, double *gy) {
    *gx = (f(x + h, y) - f(x - h, y)) / (2 * h);
    *gy = (f(x, y + h) - f(x, y - h)) / (2 * h);
}

