def calc(p):
    import math
    w0 = max(1e-3, p.get('w0', 10.0))
    zeta = p.get('zeta', 0.5)
    sigma = -zeta * w0
    if zeta < 1.0:
        wd = w0 * math.sqrt(1.0 - zeta**2)
    else:
        wd = 0.0
    return {'pole_real': round(sigma, 4), 'pole_imag': round(wd, 4), 'wn_rad_s': round(w0, 4), 'final_step_value': 1.0}
